    {α : Type*} {m0 : MeasurableSpace α} {p : ℝ≥0∞}
    {μ : Measure α} {c : ℝ≥0} {f : α → ε} : eLpNorm (c • f) p μ ≤ ‖c‖ₑ * eLpNorm f p μ

theorem eLpNorm_const_smul' {α : Type*} {m0 : MeasurableSpace α} {p : ℝ≥0∞}
    {μ : Measure α} {c : ℝ≥0} {f : α → ε'} :
    eLpNorm (c • f) p μ = ‖c‖ₑ * eLpNorm f p μ

theorem eLpNorm_top_smul
    {α : Type*} {m0 : MeasurableSpace α} {p : ℝ≥0∞}
    {μ : Measure α} {f : α → ℝ≥0∞} (hf : AEStronglyMeasurable f μ) : eLpNorm (∞ • f) p μ = ⊤ * eLpNorm f p μ

lemma IntervalIntegrable.bdd_mul {F : Type*} [NormedDivisionRing F] {f g : ℝ → F} {a b : ℝ}
    {μ : Measure ℝ} (hg : IntervalIntegrable g μ a b) (hm : AEStronglyMeasurable f μ)
    (hfbdd : ∃ C, ∀ x, ‖f x‖ ≤ C) : IntervalIntegrable (fun x ↦ f x * g x) μ a b

lemma IntervalIntegrable.mul_bdd {F : Type*} [NormedField F] {f g : ℝ → F} {a b : ℝ}
    {μ : Measure ℝ} (hf : IntervalIntegrable f μ a b) (hm : AEStronglyMeasurable g μ)
    (hgbdd : ∃ C, ∀ x, ‖g x‖ ≤ C) : IntervalIntegrable (fun x ↦ f x * g x) μ a b

lemma IntegrableOn.sub {α : Type*} {β : Type*} {m : MeasurableSpace α} {μ : Measure α}
    [NormedAddCommGroup β] {s : Set α} {f g : α → β}
    (hf : IntegrableOn f s μ) (hg : IntegrableOn g s μ) : IntegrableOn (f - g) s μ

lemma continuous_of_iLipENorm_ne_top {z : X} {R : ℝ}
    {φ : X → 𝕜} (hφ : tsupport φ ⊆ ball z R) (h'φ : iLipENorm φ z R ≠ ⊤) :
    Continuous φ

theorem iSup_eq_iSup {α : Type*} {ι ι' : Sort*} [CompleteLattice α] {f : ι → α} {g : ι' → α}
  (h₀ : ∀ i, ∃ j, f i ≤ g j) (h₁ : ∀ j, ∃ i, g j ≤ f i) :
    ⨆ i, f i = ⨆ j, g j

lemma ContinuousWithinAt.measure_lt_ne_zero {α : Type*} {m : MeasurableSpace α} {μ : Measure α}
    [TopologicalSpace α] [LinearOrder α] [DenselyOrdered α]
    [OrderTopology α] [ClosedIicTopology α] [μ.IsOpenPosMeasure] {f : α → ℝ≥0∞} {x : α}
    (hx : ¬IsMax x) (hf : ContinuousWithinAt f (Set.Ioi x) x)
    {a : ℝ≥0∞} (ha : a < f x) :
    μ {y | a < f y} ≠ 0

theorem aestronglyMeasurable {t T : ℝ} [hT : Fact (0 < T)] {f : ℝ → ℂ}
  (periodic_f : f.Periodic T) (hf : AEStronglyMeasurable f (volume.restrict (Ioc t (t + T)))) :
    AEStronglyMeasurable f

theorem aestronglyMeasurable_iff {t T : ℝ} [hT : Fact (0 < T)] {f : ℝ → ℂ}
  (periodic_f : f.Periodic T) :
    AEStronglyMeasurable f ↔ AEStronglyMeasurable f (volume.restrict (Ioc t (t + T)))

theorem MeasureTheory.eLpNorm_eq_eLpNorm_liftIoc {T : ℝ} [hT : Fact (0 < T)] {t : ℝ} {f : ℝ → ℂ}
  (hf : AEStronglyMeasurable f (volume.restrict (Ioc t (t + T)))) {p : ℝ≥0∞} :
    eLpNorm f p (volume.restrict (Ioc t (t + T))) = eLpNorm (AddCircle.liftIoc T t f) p volume

theorem MeasureTheory.eLpNorm_eq_eLpNorm_liftIoc' {T : ℝ} [hT : Fact (0 < T)] {t : ℝ}
  {f : (AddCircle T) → ℂ} (hf : AEStronglyMeasurable f volume) {p : ℝ≥0∞} :
    eLpNorm (fun (x : ℝ) ↦ f x) p (volume.restrict (Ioc t (t + T))) = eLpNorm f p volume

